SELECT 
FROM pro_dispatch WHERE is_deleted = 0

    AND dispatch_no LIKE CONCAT('%', #{dispatchNo}, '%')


    AND work_order_id = #{workOrderId}


    AND production_line = #{productionLine}


    AND status = #{status}


    AND assignee_id = #{assigneeId}

ORDER BY id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM pro_dispatch WHERE is_deleted = 0

    AND dispatch_no LIKE CONCAT('%', #{dispatchNo}, '%')


    AND work_order_id = #{workOrderId}


    AND production_line = #{productionLine}


    AND status = #{status}


    AND assignee_id = #{assigneeId}
